package evaluationplane

import (
	_ "embed"
	"fmt"
	"regexp"
	"sort"
	"sync"
)

const researchBenchmarkInventorySchemaVersion = "evaluation-research-benchmark-inventory.v1"

// The canonical file is the package-safe Python asset at
// src/vllm-sr/cli/evaluation/golden/research_benchmark_inventory.v1.json. This
// embedded mirror keeps the Go service self-contained. It is generated by
// tools/ci/sync_evaluation_catalogs.py and byte-for-byte gated in CI.
//
//go:embed research_benchmark_inventory.v1.json
var researchBenchmarkInventoryJSON []byte

// ResearchBenchmark is the single honest inventory of the research benchmarks
// audited by the evaluation plane. It deliberately describes
// method readiness, not an assertion that the upstream runner was executed.
type ResearchBenchmark struct {
	AdapterID           string        `json:"adapter_id"`
	Name                string        `json:"name"`
	DecisionUnit        string        `json:"decision_unit"`
	ActionSpace         string        `json:"action_space"`
	MethodID            string        `json:"method_id"`
	Status              string        `json:"status"`
	NativeParity        string        `json:"native_parity"`
	EvidenceCeiling     EvidenceLevel `json:"evidence_ceiling"`
	ExecutionOwner      string        `json:"execution_owner"`
	InputSchema         string        `json:"input_schema"`
	ExportSchema        string        `json:"export_schema"`
	ApplicableTracks    []TrackID     `json:"applicable_tracks"`
	ImportTracks        []TrackID     `json:"import_tracks"`
	ProducedMetricIDs   []string      `json:"produced_metric_ids"`
	RequiredArtifactIDs []string      `json:"required_artifact_ids"`
	AnalysisPlanID      string        `json:"analysis_plan_id"`
	AnalysisUnit        string        `json:"analysis_unit"`
	CurveDomain         string        `json:"curve_domain"`
	SourceRevision      string        `json:"source_revision"`
	DatasetRevision     *string       `json:"dataset_revision,omitempty"`
}

type researchBenchmarkInventoryDocument struct {
	SchemaVersion string              `json:"schema_version"`
	Benchmarks    []ResearchBenchmark `json:"benchmarks"`
}

var researchBenchmarkRevisionPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)

var (
	researchBenchmarkInventoryOnce sync.Once
	researchBenchmarks             []ResearchBenchmark
	researchBenchmarksByAdapter    map[string]ResearchBenchmark
	researchBenchmarkInventoryErr  error
)

func loadResearchBenchmarkInventory() {
	researchBenchmarks, researchBenchmarkInventoryErr = decodeResearchBenchmarkInventory()
	if researchBenchmarkInventoryErr != nil {
		// A catalog declaration must never prevent the management service from
		// starting. Validation is exposed to tests and callers; catalog lookups
		// fail closed by returning no research adapter until the declaration is
		// repaired.
		researchBenchmarks = nil
		researchBenchmarksByAdapter = map[string]ResearchBenchmark{}
		return
	}
	researchBenchmarksByAdapter = indexResearchBenchmarks(researchBenchmarks)
}

func decodeResearchBenchmarkInventory() ([]ResearchBenchmark, error) {
	return decodeResearchBenchmarkInventoryJSON(researchBenchmarkInventoryJSON)
}

func decodeResearchBenchmarkInventoryJSON(data []byte) ([]ResearchBenchmark, error) {
	var document researchBenchmarkInventoryDocument
	if err := decodeExactJSON(data, &document); err != nil {
		return nil, fmt.Errorf("decode research benchmark inventory: %w", err)
	}
	if document.SchemaVersion != researchBenchmarkInventorySchemaVersion || len(document.Benchmarks) == 0 {
		return nil, fmt.Errorf("research benchmark inventory has an invalid envelope")
	}
	for _, benchmark := range document.Benchmarks {
		if err := validateResearchBenchmark(benchmark); err != nil {
			return nil, fmt.Errorf("research benchmark inventory %q is invalid: %w", benchmark.AdapterID, err)
		}
	}
	sort.Slice(document.Benchmarks, func(left, right int) bool {
		return document.Benchmarks[left].AdapterID < document.Benchmarks[right].AdapterID
	})
	if err := validateDistinctResearchBenchmarkIDs(document.Benchmarks); err != nil {
		return nil, err
	}
	return document.Benchmarks, nil
}

func validateDistinctResearchBenchmarkIDs(benchmarks []ResearchBenchmark) error {
	seen := make(map[string]struct{}, len(benchmarks))
	for _, benchmark := range benchmarks {
		if _, duplicate := seen[benchmark.AdapterID]; duplicate {
			return fmt.Errorf("research benchmark inventory contains duplicate adapter id %q", benchmark.AdapterID)
		}
		seen[benchmark.AdapterID] = struct{}{}
	}
	return nil
}

func validateResearchBenchmark(benchmark ResearchBenchmark) error {
	if !portableIDPattern.MatchString(benchmark.AdapterID) || benchmark.Name == "" || benchmark.DecisionUnit == "" || benchmark.ActionSpace == "" ||
		!validMethodID(benchmark.MethodID) || !researchBenchmarkRevisionPattern.MatchString(benchmark.SourceRevision) ||
		(benchmark.DatasetRevision != nil && !researchBenchmarkRevisionPattern.MatchString(*benchmark.DatasetRevision)) {
		return fmt.Errorf("benchmark identity is invalid")
	}
	method := researchBenchmarkMethod(benchmark)
	if err := ValidateEvaluationMethodDefinition(method); err != nil {
		return fmt.Errorf("benchmark %q method declaration: %w", benchmark.AdapterID, err)
	}
	if benchmark.Status == "blocked" && len(benchmark.ImportTracks) != 0 {
		return fmt.Errorf("blocked benchmark %q cannot advertise an import track", benchmark.AdapterID)
	}
	if benchmark.EvidenceCeiling != "E0" || benchmark.NativeParity == "native" || benchmark.Status == "native-qualified" {
		return fmt.Errorf("benchmark %q overstates unqualified evidence", benchmark.AdapterID)
	}
	for _, track := range benchmark.ImportTracks {
		if !containsTrack(benchmark.ApplicableTracks, track) {
			return fmt.Errorf("benchmark %q import track is not applicable", benchmark.AdapterID)
		}
	}
	return nil
}

func indexResearchBenchmarks(benchmarks []ResearchBenchmark) map[string]ResearchBenchmark {
	indexed := make(map[string]ResearchBenchmark, len(benchmarks))
	for _, benchmark := range benchmarks {
		indexed[benchmark.AdapterID] = copyResearchBenchmark(benchmark)
	}
	return indexed
}

func copyResearchBenchmark(benchmark ResearchBenchmark) ResearchBenchmark {
	benchmark.ApplicableTracks = append([]TrackID(nil), benchmark.ApplicableTracks...)
	benchmark.ImportTracks = append([]TrackID(nil), benchmark.ImportTracks...)
	benchmark.ProducedMetricIDs = append([]string(nil), benchmark.ProducedMetricIDs...)
	benchmark.RequiredArtifactIDs = append([]string(nil), benchmark.RequiredArtifactIDs...)
	if benchmark.DatasetRevision != nil {
		value := *benchmark.DatasetRevision
		benchmark.DatasetRevision = &value
	}
	return benchmark
}

// ResearchBenchmarkInventory returns copies so catalog/API projections cannot
// mutate the compile-time inventory used for method admission.
func ResearchBenchmarkInventory() []ResearchBenchmark {
	researchBenchmarkInventoryOnce.Do(loadResearchBenchmarkInventory)
	benchmarks := make([]ResearchBenchmark, len(researchBenchmarks))
	for index, benchmark := range researchBenchmarks {
		benchmarks[index] = copyResearchBenchmark(benchmark)
	}
	return benchmarks
}

// ValidateResearchBenchmarkInventory exposes the embedded declaration as an
// ordinary validation error. NewRegistry invokes this gate, so a malformed
// benchmark inventory cannot produce a partial Evaluation catalog, while the
// package still avoids process-wide initialization panics.
func ValidateResearchBenchmarkInventory() error {
	researchBenchmarkInventoryOnce.Do(loadResearchBenchmarkInventory)
	return researchBenchmarkInventoryErr
}

func researchBenchmarkByAdapter(adapterID string) (ResearchBenchmark, bool) {
	researchBenchmarkInventoryOnce.Do(loadResearchBenchmarkInventory)
	benchmark, found := researchBenchmarksByAdapter[adapterID]
	return copyResearchBenchmark(benchmark), found
}

func researchBenchmarkMethod(benchmark ResearchBenchmark) EvaluationMethodDefinition {
	return EvaluationMethodDefinition{
		SchemaVersion: EvaluationMethodContractVersion, ID: benchmark.MethodID,
		Version: EvaluationMethodContractVersion, Status: benchmark.Status, ExecutionOwner: benchmark.ExecutionOwner,
		InputSchema: benchmark.InputSchema, ExportSchema: benchmark.ExportSchema,
		LiveInputComplete: false, LiveGrader: false,
		ApplicableTracks: append([]TrackID(nil), benchmark.ApplicableTracks...), LiveTracks: []TrackID{},
		ProducedMetricIDs: append([]string(nil), benchmark.ProducedMetricIDs...), EvidenceCeiling: benchmark.EvidenceCeiling,
		NativeParity: benchmark.NativeParity, RequiredArtifactIDs: append([]string(nil), benchmark.RequiredArtifactIDs...),
		AnalysisPlan: AnalysisPlan{
			SchemaVersion: EvaluationMethodContractVersion, ID: benchmark.AnalysisPlanID,
			AnalysisUnit: benchmark.AnalysisUnit, ClusterUnit: "case", Slices: []SliceRef{{SchemaVersion: EvaluationMethodContractVersion, ID: "all"}},
			CurveDomain: benchmark.CurveDomain, Missingness: "fail_closed",
		},
	}
}
